def count_passing_ways(n, m):
    if n == 1:
        return 1
    if m == 1:
        return 1
    dp = [[0] * n for _ in range(m + 1)]
    dp[1][1] = 1
    for i in range(2, n + 1):
        for j in range(1, m + 1):
            dp[j][i] = (dp[j - 1][i - 1] + dp[j][i - 1]) % 1000000007
    return dp[m][n]

