def calculate_arrangements(n, m, a):
    # Initialization
    dp = [0] * (m + 1)
    dp[0] = 1
    mod = 1000000 + 7

    # Compute the number of arrangements for each flower type
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if j - a[i - 1] >= 0:
                dp[j] = (dp[j] + dp[j - a[i - 1]]) % mod

    return dp[m]

def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    if n == 2:
        return 6
    if n == 3:
        return 14

    # Initialize variables
    moves = 0
    n_2 = n * 2

    # Compute the minimum number of moves for each sub-problem
    for size in range(n - 1, 0, -1):
        moves += (2 ** (size - 1)) * (n_2 - size)

    # Return the minimum number of moves
    return moves
